/** Error raised for malformed paths and impossible requests. */
export class PathError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'PathError';
    this.code = code;
  }
}

/**
 * Validate that every argument is a non-NUL string, left to right.
 * These two checks run before anything else.
 *
 * @param {...*} args Arguments to validate.
 */
function validateArgs(args) {
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (typeof arg !== 'string') {
      throw new PathError('NOT_A_STRING', 'path must be a string');
    }
  }
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.includes('\u0000')) {
      throw new PathError('NUL_BYTE', 'path contains a NUL byte');
    }
  }
}

/**
 * Report whether a path starts at the root.
 *
 * @param {string} path Path to inspect.
 * @returns {boolean} True for a rooted path.
 */
export function isAbsolute(path) {
  validateArgs([path]);
  return path.length > 0 && path.charCodeAt(0) === 47;
}

/**
 * Collapse `.`, `..`, repeated slashes and trailing slashes.
 *
 * @param {string} path Path to normalize.
 * @returns {string} Normalized path.
 */
export function normalize(path) {
  validateArgs([path]);
  if (path === '') {
    throw new PathError('EMPTY_PATH', 'path must not be empty');
  }

  const rooted = path.charCodeAt(0) === 47;
  const segments = path.split('/');
  const out = [];

  for (const seg of segments) {
    if (seg === '' || seg === '.') {
      continue;
    }
    if (seg === '..') {
      if (out.length > 0 && out[out.length - 1] !== '..') {
        out.pop();
      } else if (rooted) {
        throw new PathError('ESCAPE', `path escapes root: ${path}`);
      } else {
        out.push('..');
      }
      continue;
    }
    out.push(seg);
  }

  if (rooted) {
    if (out.length === 0) {
      return '/';
    }
    return '/' + out.join('/');
  }

  if (out.length === 0) {
    return '.';
  }
  return out.join('/');
}

/**
 * Join segments and normalize the result.
 *
 * @param {...string} segments One or more path segments.
 * @returns {string} Normalized joined path.
 */
export function join(...segments) {
  validateArgs(segments);

  if (segments.length === 0) {
    throw new PathError('NO_SEGMENTS', 'join requires at least one segment');
  }

  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];
    if (seg === '') {
      throw new PathError('EMPTY_SEGMENT', `segment ${i} must not be empty`);
    }
  }

  for (let i = 1; i < segments.length; i++) {
    const seg = segments[i];
    if (seg.charCodeAt(0) === 47) {
      throw new PathError('ABSOLUTE_SEGMENT', `segment ${i} must be relative`);
    }
  }

  const joined = segments.join('/');
  return normalize(joined);
}

/**
 * Path from one absolute location to another.
 *
 * @param {string} from Absolute starting path.
 * @param {string} to Absolute destination path.
 * @returns {string} Relative path, empty when the two are the same.
 */
export function relative(from, to) {
  validateArgs([from, to]);

  if (!isAbsolute(from) || !isAbsolute(to)) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }

  const fromNorm = normalize(from);
  const toNorm = normalize(to);

  const fromParts = fromNorm === '/' ? [] : fromNorm.slice(1).split('/');
  const toParts = toNorm === '/' ? [] : toNorm.slice(1).split('/');

  let common = 0;
  const limit = Math.min(fromParts.length, toParts.length);
  while (common < limit && fromParts[common] === toParts[common]) {
    common++;
  }

  const upCount = fromParts.length - common;
  const down = toParts.slice(common);

  if (upCount === 0 && down.length === 0) {
    return '';
  }

  const result = [];
  for (let i = 0; i < upCount; i++) {
    result.push('..');
  }
  for (const d of down) {
    result.push(d);
  }
  return result.join('/');
}
